package com.example.projectilesim;

import com.badlogic.gdx.math.Vector2;
import com.badlogic.gdx.utils.Pool;

/**
 * A single projectile participating in the simulation.
 *
 * <p>Instances of this class are recycled by a {@link Pool}&lt;Projectile&gt;,
 * so all mutable state must be initialised inside {@link #reset()} to keep
 * an {@link #obtain() obtained} instance deterministic regardless of how it
 * was previously used.</p>
 *
 * <p>The position and velocity are stored in libGDX {@link Vector2}
 * instances.  Although {@code Vector2} stores {@code float}s the
 * simulation only ever performs integer arithmetic on its components,
 * so values can be safely cast to {@code int} when emitting log lines.</p>
 */
public class Projectile implements Pool.Poolable {

    /** Spawn identifier: assigned in the order SPAWN lines appear in the scenario. */
    public int id = -1;

    /** Current integer position in scenario space. */
    public final Vector2 position = new Vector2();

    /** Current integer velocity in scenario space (units per tick). */
    public final Vector2 velocity = new Vector2();

    /**
     * Initialise this instance with the supplied id and integer state.
     *
     * @param id  unique spawn identifier
     * @param x   initial x position
     * @param y   initial y position
     * @param vx  initial x velocity (units/tick)
     * @param vy  initial y velocity (units/tick)
     */
    public void init(int id, int x, int y, int vx, int vy) {
        this.id = id;
        this.position.set(x, y);
        this.velocity.set(vx, vy);
    }

    /**
     * Reset every field to a known default.  Required by
     * {@link Pool.Poolable} and called every time the projectile is
     * returned to the pool via {@link Pool#free(Object)}.
     */
    @Override
    public void reset() {
        this.id = -1;
        this.position.set(0, 0);
        this.velocity.set(0, 0);
    }
}

package com.example.projectilesim;

import com.badlogic.gdx.math.Vector2;

import java.util.ArrayList;
import java.util.List;

/**
 * In-memory representation of a parsed scenario file.
 *
 * <p>Once populated, the fields are read-only for the duration of the run.</p>
 */
public final class Scenario {

    /** Number of render() ticks to execute (parameter to {@code TICKS}). */
    public int ticks;

    /** Per-tick acceleration applied to every active projectile's velocity. */
    public final Vector2 gravity = new Vector2();

    /** Floor y-coordinate; projectiles with {@code y <= floorY} ground. */
    public int floorY;

    /**
     * All spawn directives in the order they appeared in the file.
     * Each spawn's id is its index in this list.
     */
    public final List<SpawnDirective> spawns = new ArrayList<>();

    /** A single SPAWN directive. */
    public static final class SpawnDirective {
        public final int tick;
        public final int x;
        public final int y;
        public final int vx;
        public final int vy;

        public SpawnDirective(int tick, int x, int y, int vx, int vy) {
            this.tick = tick;
            this.x = x;
            this.y = y;
            this.vx = vx;
            this.vy = vy;
        }
    }
}

package com.example.projectilesim;

import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.files.FileHandle;

/**
 * Reader for scenario files.
 *
 * <p>Scenarios are UTF-8 text files containing one directive per line.
 * Lines starting with {@code #} (after trimming) and blank lines are
 * ignored.  Recognised directives are {@code TICKS}, {@code GRAVITY},
 * {@code FLOOR} and {@code SPAWN}.</p>
 */
public final class ScenarioParser {

    private ScenarioParser() {
        // utility class
    }

    /**
     * Read and parse the scenario file at {@code absolutePath} using
     * libGDX's file abstraction ({@link Gdx#files}) so that the simulation
     * exercises the same IO surface as any other libGDX application.
     */
    public static Scenario parse(String absolutePath) {
        FileHandle handle = Gdx.files.absolute(absolutePath);
        if (!handle.exists()) {
            throw new IllegalArgumentException(
                "Scenario file does not exist: " + absolutePath);
        }
        String text = handle.readString("UTF-8");
        return parseText(text, absolutePath);
    }

    /**
     * Pure parser variant.  Public-for-tests style: can be exercised with a
     * literal string without going through libGDX file IO.
     *
     * @param text          scenario body, UTF-8 decoded
     * @param sourceLabel   used solely for error messages
     */
    public static Scenario parseText(String text, String sourceLabel) {
        Scenario scenario = new Scenario();
        boolean hasTicks = false;
        boolean hasGravity = false;
        boolean hasFloor = false;

        String[] rawLines = text.split("\\r?\\n", -1);
        int lineNumber = 0;
        for (String raw : rawLines) {
            lineNumber++;
            String line = raw.trim();
            if (line.isEmpty() || line.startsWith("#")) {
                continue;
            }
            String[] tok = line.split("\\s+");
            if (tok.length == 0) {
                continue;
            }
            String head = tok[0];
            try {
                switch (head) {
                    case "TICKS": {
                        requireArity(tok, 2, "TICKS", sourceLabel, lineNumber);
                        scenario.ticks = parseInt(tok[1], "TICKS", sourceLabel, lineNumber);
                        hasTicks = true;
                        break;
                    }
                    case "GRAVITY": {
                        requireArity(tok, 3, "GRAVITY", sourceLabel, lineNumber);
                        int gx = parseInt(tok[1], "GRAVITY", sourceLabel, lineNumber);
                        int gy = parseInt(tok[2], "GRAVITY", sourceLabel, lineNumber);
                        scenario.gravity.set(gx, gy);
                        hasGravity = true;
                        break;
                    }
                    case "FLOOR": {
                        requireArity(tok, 2, "FLOOR", sourceLabel, lineNumber);
                        scenario.floorY = parseInt(tok[1], "FLOOR", sourceLabel, lineNumber);
                        hasFloor = true;
                        break;
                    }
                    case "SPAWN": {
                        requireArity(tok, 6, "SPAWN", sourceLabel, lineNumber);
                        int at = parseInt(tok[1], "SPAWN", sourceLabel, lineNumber);
                        int x = parseInt(tok[2], "SPAWN", sourceLabel, lineNumber);
                        int y = parseInt(tok[3], "SPAWN", sourceLabel, lineNumber);
                        int vx = parseInt(tok[4], "SPAWN", sourceLabel, lineNumber);
                        int vy = parseInt(tok[5], "SPAWN", sourceLabel, lineNumber);
                        scenario.spawns.add(
                            new Scenario.SpawnDirective(at, x, y, vx, vy));
                        break;
                    }
                    default:
                        throw new IllegalArgumentException(
                            "Unknown directive '" + head + "' in "
                                + sourceLabel + " at line " + lineNumber);
                }
            } catch (IllegalArgumentException ex) {
                // Preserve original cause but rewrite path/line for the user.
                throw new IllegalArgumentException(
                    ex.getMessage()
                        + " (in " + sourceLabel + " at line " + lineNumber + ")",
                    ex);
            }
        }

        if (!hasTicks) {
            throw new IllegalArgumentException(
                "Scenario is missing required TICKS directive: " + sourceLabel);
        }
        if (!hasGravity) {
            throw new IllegalArgumentException(
                "Scenario is missing required GRAVITY directive: " + sourceLabel);
        }
        if (!hasFloor) {
            throw new IllegalArgumentException(
                "Scenario is missing required FLOOR directive: " + sourceLabel);
        }
        return scenario;
    }

    private static void requireArity(String[] tok, int expected, String directive,
                                     String source, int line) {
        if (tok.length < expected) {
            throw new IllegalArgumentException(
                "Directive " + directive + " expects " + (expected - 1)
                    + " arguments");
        }
    }

    private static int parseInt(String s, String directive, String source, int line) {
        try {
            return Integer.parseInt(s);
        } catch (NumberFormatException ex) {
            throw new IllegalArgumentException(
                "Invalid integer '" + s + "' for directive " + directive, ex);
        }
    }
}

package com.example.projectilesim;

import com.badlogic.gdx.ApplicationAdapter;
import com.badlogic.gdx.utils.Pool;

import java.io.BufferedWriter;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;

/**
 * Headless {@link com.badlogic.gdx.ApplicationListener} that drives the
 * deterministic projectile simulation.
 *
 * <p>The listener opens the scenario inside {@link #create()} (so
 * {@link com.badlogic.gdx.Gdx#files} is initialised), then advances the
 * simulation by exactly one tick per {@link #render()} call.  When the
 * requested tick count is reached, {@code Gdx.app.exit()} is invoked
 * which causes {@link com.badlogic.gdx.backends.headless.HeadlessApplication}
 * to dispose the listener and terminate cleanly.</p>
 */
public class SimulationListener extends ApplicationAdapter {

    /** Absolute path of the scenario file. */
    private final String scenarioPath;
    /** Absolute path of the output log file. */
    private final String outputPath;

    /** Pool of recycled {@link Projectile} instances. */
    private final Pool<Projectile> pool = new Pool<Projectile>() {
        @Override
        protected Projectile newObject() {
            return new Projectile();
        }
    };

    /** Active projectiles, kept sorted by ascending spawn id (order of obtain()). */
    private final List<Projectile> active = new ArrayList<>();

    /** Per-tick list of grounded projectile ids (cleared each tick after printing). */
    private final List<Integer> groundedThisTick = new ArrayList<>();

    /** Parsed scenario. */
    private Scenario scenario;

    /** Buffered writer to the output log.  Opened in create(), closed in dispose(). */
    private BufferedWriter writer;

    /** Counter used to assign spawn ids in SPAWN-file order. */
    private int nextSpawnId;

    /** Total projectiles spawned (one per SPAWN directive processed). */
    private int spawnedCount;

    /** Total projectiles grounded during the entire run. */
    private int groundedCount;

    /** Maximum active.size() observed across the entire run. */
    private int peakActive;

    /** Current tick.  First render() is tick 0. */
    private int currentTick;

    public SimulationListener(String scenarioPath, String outputPath) {
        this.scenarioPath = scenarioPath;
        this.outputPath = outputPath;
    }

    @Override
    public void create() {
        try {
            // 1. Open the output file before anything else so that any parse /
            //    IO error is reported into the log.
            Path out = Paths.get(outputPath);
            if (out.getParent() != null) {
                Files.createDirectories(out.getParent());
            }
            this.writer = Files.newBufferedWriter(out, StandardCharsets.UTF_8);

            // 2. Parse the scenario.
            this.scenario = ScenarioParser.parse(scenarioPath);

            // 3. Echo the header line.  The spec requires `TICKS <n>` as the
            //    first non-summary line of the output.
            writeLine("TICKS " + scenario.ticks);

            // Initial peak record (in case the scenario has zero spawns and
            // tick 0 is the only place we observe `active.size()`).
            if (active.size() > peakActive) {
                peakActive = active.size();
            }
        } catch (IOException ex) {
            throw new RuntimeException("Failed to initialise output: " + outputPath, ex);
        } catch (RuntimeException ex) {
            throw ex;
        }
    }

    @Override
    public void render() {
        // A single render() == a single tick.  The spec is explicit that
        // we must not derive the physics step from `Gdx.graphics.getDeltaTime()`.
        int t = currentTick;
        try {
            // 1. Process every SPAWN scheduled for this tick, in file order.
            for (Scenario.SpawnDirective spawn : scenario.spawns) {
                if (spawn.tick != t) continue;
                Projectile p = pool.obtain();
                p.init(nextSpawnId, spawn.x, spawn.y, spawn.vx, spawn.vy);
                nextSpawnId++;
                spawnedCount++;
                active.add(p);
            }
            // After spawns, peak_active is potentially maximum for this tick.
            if (active.size() > peakActive) {
                peakActive = active.size();
            }

            // 2. Apply gravity and integrate for every active projectile,
            //    in ascending spawn-id order.
            for (Projectile p : active) {
                p.velocity.x += scenario.gravity.x;
                p.velocity.y += scenario.gravity.y;
                p.position.x += p.velocity.x;
                p.position.y += p.velocity.y;
            }

            // 3. Ground everything below the floor.  Iterate in reverse so
            //    removals don't disturb indices of items we still need to
            //    inspect.  Accumulate ids of grounded projectiles so we
            //    can print them in ascending order afterwards.
            groundedThisTick.clear();
            for (int i = active.size() - 1; i >= 0; i--) {
                Projectile p = active.get(i);
                if (p.position.y <= scenario.floorY) {
                    groundedThisTick.add(p.id);
                    active.remove(i);
                    pool.free(p);
                }
            }
            // Sort ascending to satisfy the spec's output order.
            groundedThisTick.sort(Integer::compare);

            // 4. Emit this tick's block.
            writeLine("TICK " + t + " ACTIVE " + active.size());
            for (Projectile p : active) {
                writeLine(formatProjectile(p));
            }
            for (Integer id : groundedThisTick) {
                writeLine("GROUNDED P" + id + " tick=" + t);
                groundedCount++;
            }

            // 5. Tick bookkeeping.
            currentTick++;
            if (currentTick >= scenario.ticks) {
                emitSummary();
                // Gdx.app.exit() schedules orderly shutdown; HeadlessApplication
                // will then call our dispose() and the JVM will exit once
                // the launcher main() has re-joined our thread.
                com.badlogic.gdx.Gdx.app.exit();
            }
        } catch (IOException ex) {
            throw new RuntimeException("Failed while writing log at tick " + t, ex);
        }
    }

    @Override
    public void dispose() {
        if (writer != null) {
            try {
                writer.flush();
                writer.close();
            } catch (IOException ex) {
                // Disposal is best-effort; the file may already be closed.
            } finally {
                writer = null;
            }
        }
    }

    /** Append a single newline-terminated line to the log. */
    private void writeLine(String s) throws IOException {
        writer.write(s);
        writer.write('\n');
    }

    private String formatProjectile(Projectile p) {
        return "P" + p.id
            + " x=" + (int) p.position.x
            + " y=" + (int) p.position.y
            + " vx=" + (int) p.velocity.x
            + " vy=" + (int) p.velocity.y;
    }

    private void emitSummary() throws IOException {
        writeLine("SUMMARY spawned=" + spawnedCount
            + " grounded=" + groundedCount
            + " pool_free=" + pool.getFree()
            + " peak_active=" + peakActive);
    }
}

package com.example.projectilesim;

import com.badlogic.gdx.backends.headless.HeadlessApplication;
import com.badlogic.gdx.backends.headless.HeadlessApplicationConfiguration;

/**
 * Entry point for the headless projectile simulation.
 *
 * <p>Bootstraps a {@link HeadlessApplication} (hosted on its own thread)
 * with a {@link SimulationListener} configured from the
 * {@code --scenario} and {@code --output} command line flags.  The launcher
 * parses the flags itself because the inner Gradle {@code application}
 * plugin's standard {@code --args} splitting doesn't quite cover the
 * verifier's invocation form.</p>
 *
 * <p>After the headless application signals completion
 * (via {@code Gdx.app.exit()}), this thread joins the application thread
 * so the JVM does not terminate mid-flush.</p>
 */
public final class Launcher {

    private Launcher() {
    }

    public static void main(String[] args) throws InterruptedException {
        ParsedArgs parsed = ParsedArgs.parse(args);

        HeadlessApplicationConfiguration cfg = new HeadlessApplicationConfiguration();
        // 0 = no cap, run as fast as the scheduler will let us: ideal for CI.
        cfg.updatesPerSecond = 0;

        HeadlessApplication app = new HeadlessApplication(
            new SimulationListener(parsed.scenarioPath, parsed.outputPath),
            cfg);

        // Wait for the simulation to drain.  The listener calls
        // Gdx.app.exit() after the requested number of ticks, which makes
        // HeadlessApplication eventually call dispose() on the listener and
        // exit its main loop.
        while (app.getApplicationListener() != null) {
            Thread.sleep(50L);
        }
        // At this point HeadlessApplication.run() has returned.  Block briefly
        // to allow the dispose() path to finish flushing the buffered writer.
        Thread.sleep(50L);
    }

    /** Lightweight argv parser for {@code --scenario PATH --output PATH}. */
    static final class ParsedArgs {
        final String scenarioPath;
        final String outputPath;

        private ParsedArgs(String scenarioPath, String outputPath) {
            this.scenarioPath = scenarioPath;
            this.outputPath = outputPath;
        }

        static ParsedArgs parse(String[] argv) {
            String scenario = null;
            String output = null;
            for (int i = 0; i < argv.length; i++) {
                switch (argv[i]) {
                    case "--scenario":
                        if (++i >= argv.length) {
                            fail("--scenario requires a value");
                        }
                        scenario = argv[i];
                        break;
                    case "--output":
                        if (++i >= argv.length) {
                            fail("--output requires a value");
                        }
                        output = argv[i];
                        break;
                    default:
                        // Ignore unknown tokens.  Gradle / wrapper tooling
                        // sometimes injects things like "--console=plain".
                        break;
                }
            }
            if (scenario == null || scenario.isEmpty()) {
                fail("--scenario <path> is required");
            }
            if (output == null || output.isEmpty()) {
                fail("--output <path> is required");
            }
            return new ParsedArgs(scenario, output);
        }

        private static void fail(String msg) {
            System.err.println("Launcher: " + msg);
            System.exit(2);
        }
    }
}

